SELECT int32 = int8 AS c0, toTypeName(int32 = int8) AS t0, int32 != int8 AS c1, toTypeName(int32 != int8) AS t1, int32 < int8 AS c2, toTypeName(int32 < int8) AS t2, int32 <= int8 AS c3, toTypeName(int32 <= int8) AS t3, int32 > int8 AS c4, toTypeName(int32 > int8) AS t4, int32 >= int8 AS c5, toTypeName(int32 >= int8) AS t5 FROM he24.numeric ORDER BY row_id
